function setRange(months){
 const next=Math.max(1,Math.min(36,Math.round(months*2)/2));
 if(Math.abs(next-rangeMonths)<.001)return;
 rangeMonths=next;
 const nearest=[6,12,24].find(x=>Math.abs(x-rangeMonths)<.05);
 rangeSelect.value=nearest?String(nearest):'custom';
 rangeSelect.querySelector('[value=custom]').textContent='未来 '+rangeMonths+' 个月';
 zoomValue.textContent='未来 '+rangeMonths+' 个月';
 horizonSlider.value=String(rangeMonths);
 horizonSlider.style.setProperty('--progress',((rangeMonths-1)/35*100)+'%');
 updateCandy();
 updateStats();
}
horizonSlider.addEventListener('input',e=>setRange(Number(e.target.value)));
horizonSlider.style.setProperty('--progress',((rangeMonths-1)/35*100)+'%');
updateCandy();
canvas.style.cursor='default';canvas.style.touchAction='auto';
// Wheel zoom applies only while hovering the time ruler; elsewhere the page scrolls normally.
// Stateless wheel control: one wheel action has exactly one direction.
// No residual momentum or animation lag can make the view move backwards at the limits.
const ruler=document.querySelector('.time-ruler');
let wheelLast=0;
ruler.addEventListener('wheel',e=>{
 e.preventDefault();
 e.stopPropagation();
 const dy=e.deltaY*(e.deltaMode===1?16:e.deltaMode===2?window.innerHeight:1);
 if(Math.abs(dy)<.01)return;
 const now=performance.now();
 // Rate-limit high frequency wheel events without buffering motion across the limits.
 if(now-wheelLast<45)return;
 wheelLast=now;
 setRange(rangeMonths+(dy>0?.5:-.5));
}, {passive:false,capture:true});
// Keep the browser's native range-wheel behavior from competing with the custom wheel handler.
horizonSlider.addEventListener('wheel',e=>{e.preventDefault();},{passive:false});
