function openNavigation(nav){if(nav==='探索'){closeModal(panelOverlay);return}showPanel(nav);if(nav==='我的轨迹'){if(!futurePlans.length)panelContent.append(textNode('p','尚未保存路径。在机会详情中预演一种未来，再加入我的轨迹。'));for(const p of futurePlans){const r=document.createElement('article');r.className='panel-row';r.append(textNode('h3',p.name),textNode('p','假设性规划 · '+p.goal+' · '+p.weeks+'周 / 每周'+p.hours+'小时'),textNode('p','下一步：核实资格和截止日期，列出本周最小任务。'));panelContent.append(r)}return}if(nav==='机会库'){renderLibrary();return}let list=items.map((it,i)=>({it,i}));if(nav==='收藏'){list=list.filter(x=>saved.has(x.it.id));const present=new Set(items.map(it=>it.id)),missing=[...saved].filter(id=>!present.has(id));if(missing.length)panelContent.append(textNode('p',missing.length+'项收藏不在当前资料批次中，ID已保留；恢复相应资料后会重新出现。'))}if(nav==='日程')list=list.filter(x=>x.it.end&&dateOf(x.it.end)>=TODAY).sort((a,b)=>a.it.end.localeCompare(b.it.end));if(!list.length)panelContent.append(textNode('p','暂无记录。'));appendOpportunityPages(list)}
function showPath(i){
 if(!items[i])return;const it=items[i],result=matchProfile(it);showPanel('资格路径');panelContent.append(textNode('h3',it.name));
 const facts=document.createElement('div');facts.className='panel-row path-facts';facts.append(textNode('p','身份：'+it.aud),textNode('p','范围：'+it.field+'；截止：'+deadlineText(it)),textNode('small',it.verified?'官方正文核验 '+it.checked+' · 最终以主办方审核为准':sourceReviewState(it).label));panelContent.append(facts,textNode('p','个人匹配：'+result.label));
 const reasons=document.createElement('ul');reasons.className='path-reasons';const actionable=result.code==='pending'?result.reasons.filter(r=>!/(符合已知条件$|在校状态符合$|负责人年级符合$|参赛队员人数符合已知限制$|^本人已确认)/.test(r)):result.reasons;for(const reason of actionable)reasons.append(textNode('li',reason));panelContent.append(reasons);
 const edit=textNode('button','填写或修改个人资格');edit.className='secondary';edit.onclick=()=>{closeModal(panelOverlay);openProfile()};panelContent.append(edit);appendSelfCheckForm(it);
 const detail=document.createElement('details');detail.className='path-source';detail.append(textNode('summary','公告限制与来源说明'),textNode('p',it.note),textNode('p',it.eligibility.basis));panelContent.append(detail);
 const link=textNode('a','以官方通知核实资格和材料 ↗');link.href=it.url;link.dataset.offline='true';link.rel='noopener noreferrer';panelContent.append(link);
}
document.getElementById('closePanel').onclick=()=>closeModal(panelOverlay);panelOverlay.onclick=e=>{if(e.target===panelOverlay)closeModal(panelOverlay)};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modalOpen)closeModal(modalOpen);if(e.key==='Tab'&&modalOpen){const controls=[...modalOpen.querySelectorAll('button,input,select,a[href]')].filter(n=>!n.disabled&&n.getClientRects().length);const first=controls[0],last=controls[controls.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
