function reconcileGalaxyComparison(){if(!galaxyInteraction.compared.length)return;const visible=new Set(matchingItems().map(({it})=>it.id));const previous=galaxyInteraction.compared.length;galaxyInteraction.compared=galaxyInteraction.compared.filter(id=>visible.has(id));if(previous!==galaxyInteraction.compared.length){const status=document.getElementById('galaxyStatus');if(status)status.textContent='筛选已变更，已移除不在当前星系中的对比项'}if(!galaxyInteraction.compareMode&&galaxyInteraction.compared.length!==2)galaxyInteraction.compared=[]}
