 const scrollHint=textNode('p','左右滑动查看两项，向下查看完整条件');scrollHint.className='comparison-scroll-hint';panelContent.append(scrollHint);const wrap=textNode('div','');wrap.className='comparison-wrap';const table=document.createElement('table');table.className='comparison-table';const caption=textNode('caption','两项机会的截止、范围及个人资格');caption.className='galaxy-status';table.append(caption);
